var SelectedDropdowns=0;
tinymce.PluginManager.add('ifbq_dropdown', function(editor, url) {
	
	CurrVarName = (CurrVarName) ? CurrVarName :'' ;
	editor.ui.registry.addButton('dropdowns', {
		text: 'Dropdownmenü',
		icon: 'table',
		id: 'dropdown_antwortElement',
		class: 'dropdowns',
		tooltip:'Antwortelement',
		stateSelector:"img .dropdowns",
		onAction: ShowDropdowns
	});
});
